Section LAYOUT.
Variable sptop : Z.   (* [comment removed for export] *)

Definition L0 : heap_layout := {|
  hl_segs := rsegs;
  hl_malloc := RMALLOC_SYM;          (* [comment removed for export] *)
  hl_free := RFREE_SYM;              (* [comment removed for export] *)
  hl_aligned_alloc := RAA_SYM;        (* [comment removed for export] *)
  hl_tp := RATP;                     (* [comment removed for export] *)
  hl_errno := RERRNO;                (* [comment removed for export] *)
  hl_img_lo := IMG_LO;
  hl_img_hi := IMG_HI;
  hl_alloc_static := fun a => RMLOCK <= a < RCTX + 928;                       (* [comment removed for export] *)
  hl_alloc_ro := fun a =>
       (IMG_LO <= a < 0xc0000)              (* [comment removed for export] *)
    \/ (RLIBC <= a < RMLOCK)                (* [comment removed for export] *)
    \/ (RCTX + 928 <= a < RCTX + 936)       (* [comment removed for export] *)
    \/ (RGOT_SSP <= a < RGOT_SSP + 8)       (* [comment removed for export] *)
    \/ (RSSP_GUARD <= a < RSSP_GUARD + 8)   (* [comment removed for export] *)
    \/ (RVMLOCK <= a < RVMLOCK + 4)         (* [comment removed for export] *)
    \/ (sptop <= a);                        (* [comment removed for export] *)
  hl_stack := RALIGNED_STACK;        (* [comment removed for export] *)
  hl_sptop := sptop;
  hl_k_per_malloc := KPM;
  hl_b_overhead := BOV;
  hl_K0 := K0;
  hl_B0 := B0 |}.

